            GetTree().Root.Size = new Vector2I(1200, 800); GetTree().Root.GuiEmbedSubwindows = true; var workspace = GD.Load<GDScript>("res://Workspaces/ModelWorkspace/model_workspace.gd").New().As<Control>(); AddChild(workspace); await Settle(); var session = workspace.Get("session").As<RefCounted>(); var box = session.Call("add", "Box").As<Resource>(); string id = box.Get("id").AsString(); await Settle();
