            tabs.CurrentTab = 2; var surfaces = workspace.Get("_surfaces").As<Control>(); Descendants(surfaces).OfType<Button>().Single(button => button.Text == "＋ Material").EmitSignal(BaseButton.SignalName.Pressed); await Settle(); var originalColor = ((BaseMaterial3D)Selected().Get("surface_materials").AsGodotArray<Material>()[0]).AlbedoColor; var picker = Descendants(surfaces).OfType<ColorPickerButton>().Single(); picker.EmitSignal(BaseButton.SignalName.Pressed); var editedColor = new Color(.2f, .4f, .8f); picker.EmitSignal(ColorPickerButton.SignalName.ColorChanged, editedColor); picker.EmitSignal(ColorPickerButton.SignalName.PopupClosed); await Settle(); if (!((BaseMaterial3D)Selected().Get("surface_materials").AsGodotArray<Material>()[0]).AlbedoColor.IsEqualApprox(editedColor)) throw new Exception("Native material picker did not update its cloned material."); session.Call("undo"); await Settle(); if (!((BaseMaterial3D)Selected().Get("surface_materials").AsGodotArray<Material>()[0]).AlbedoColor.IsEqualApprox(originalColor)) throw new Exception("Native material color edit did not undo."); GD.Print("PASS native material color previews clone materials and preserve undo");
            Descendants(surfaces).OfType<Button>().Single(button => button.Text == "＋ Material").EmitSignal(BaseButton.SignalName.Pressed); await Settle(); session.Set("mode", "Face"); session.Set("elements", new[] { 0 }); var materialLabel = Descendants(surfaces).OfType<Label>().Single(label => label.Text == "Material 2"); materialLabel.GetParent().GetChildren().OfType<Button>().Single(button => button.Text == "Assign").EmitSignal(BaseButton.SignalName.Pressed); await Settle(); int[] slots = Selected().Get("mesh").As<Resource>().Get("materials").AsInt32Array(); if (slots[0] != 1 || slots.Skip(1).Any(slot => slot != 0)) throw new Exception("Native material assignment did not respect the selected faces."); session.Call("undo"); await Settle(); if (Selected().Get("mesh").As<Resource>().Get("materials").AsInt32Array().Any(slot => slot != 0)) throw new Exception("Native face material assignment did not undo."); GD.Print("PASS native material assignment respects face selection and undoes");
